import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
const root = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
);

/** One local stylesheet; fonts and readable source styles remain editable separately. */
export function compileStyles() {
  const files = ["assets/fonts.css", "styles/site.css"];
  const css = files
    .map((file) => fs.readFileSync(path.join(root, file), "utf8"))
    .join("\n");
  fs.writeFileSync(
    path.join(root, "assets/perceived.css"),
    "/* Generated by npm run build. Edit styles/site.css. */\n" + css,
  );
}
